<?php require_once __DIR__ . '/../includes/layout.php'; require_role(['super_admin']); $id=(int)($_GET['id']??0); $temp='Temp'.random_int(100000,999999); $hash=password_hash($temp,PASSWORD_BCRYPT); $stmt=db()->prepare('UPDATE users SET password_hash=?, must_change_password=1 WHERE id=?'); $stmt->bind_param('si',$hash,$id); $stmt->execute(); audit('admin_password_reset','user',$id); page_header('Temporary Password'); ?><div class="panel"><h2>Password Reset Complete</h2><p>Temporary password for user #<?= e((string)$id) ?>:</p><p class="reset-link"><?= e($temp) ?></p><a class="btn btn-primary" href="index.php">Back to settings</a></div><?php page_footer(); ?>
